from datetime import datetime, timezone

TASKS = {
    1: {
        "id": 1,
        "title": "Купить молоко",
        "done": False,
        "created_at": "2026-02-11T18:30:00Z",
    },
}


def now_utc():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def all_tasks():
    return sorted(TASKS.values(), key=lambda task: task["id"])


def get(task_id):
    return TASKS.get(task_id)


def next_id(tasks):
    ids = [task["id"] for task in tasks if "id" in task]
    return max(ids) + 1 if ids else 1


def add(title, done=False):
    task_id = next_id(TASKS.values())
    task = {"id": task_id, "title": title, "done": done, "created_at": now_utc()}
    TASKS[task_id] = task
    return task


def replace(task_id, title, done):
    task = TASKS[task_id]
    task.update({"title": title, "done": done})
    return task


def patch(task_id, values):
    task = TASKS[task_id]
    task.update(values)
    return task


def remove(task_id):
    return TASKS.pop(task_id, None) is not None

TITLE_MAX_LENGTH = 200


def validate_title(value):
    if not isinstance(value, str):
        return "заголовок должен быть строкой"
    if not value.strip():
        return "заголовок не может быть пустым"
    if len(value.strip()) > TITLE_MAX_LENGTH:
        return f"заголовок не может быть длиннее {TITLE_MAX_LENGTH} символов"
    return None


def validate_done(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, str) and value.strip().lower() in ("true", "false"):
        return None
    return "done должен быть логическим значением"


def apply_patch(task, patch):
    """Частичное обновление: трогаем только title и done, id неприкосновенен."""
    updated = dict(task)
    if "title" in patch:
        updated["title"] = str(patch["title"]).strip()
    if "done" in patch:
        updated["done"] = bool(patch["done"])
    return updated

from flask import Blueprint, Response, jsonify, request, url_for

from app.tasks import service, storage

bp = Blueprint("tasks", __name__, url_prefix="/api/v1")


def api_error(status, message, field=None):
    error = {"status": status, "message": message}
    if field is not None:
        error["field"] = field
    return jsonify({"error": error}), status


def serialize(task):
    return {
        "id": task["id"],
        "title": task["title"],
        "done": task["done"],
        "created_at": task["created_at"],
        "url": url_for("tasks.task_detail", task_id=task["id"]),
    }


def read_json():
    data = request.get_json(silent=True)
    if data is None or not isinstance(data, dict):
        return None, api_error(400, "ожидали JSON-объект в теле запроса")
    return data, None


@bp.get("/tasks")
def list_tasks():
    limit = request.args.get("limit", default=20, type=int)
    offset = request.args.get("offset", default=0, type=int)
    if not 1 <= limit <= 100 or offset < 0:
        return api_error(400, "limit — от 1 до 100, offset — неотрицательный")

    items = storage.all_tasks()

    done = request.args.get("done")
    if done is not None:
        items = [t for t in items if t["done"] == (done == "true")]

    query = request.args.get("q", "").strip().lower()
    if query:
        items = [t for t in items if query in t["title"].lower()]

    total = len(items)
    page = [serialize(t) for t in items[offset:offset + limit]]
    return jsonify({"items": page, "total": total, "limit": limit, "offset": offset})


@bp.get("/tasks/<int:task_id>")
def task_detail(task_id):
    task = storage.get(task_id)
    if task is None:
        return api_error(404, "задача не найдена")
    return jsonify(serialize(task))


@bp.post("/tasks")
def create_task():
    data, failure = read_json()
    if failure is not None:
        return failure
    problem = service.validate_title(data.get("title"))
    if problem is not None:
        return api_error(422, problem, field="title")
    problem = service.validate_done(data.get("done", False))
    if problem is not None:
        return api_error(422, problem, field="done")

    task = storage.add(title=data["title"].strip(), done=bool(data.get("done", False)))
    body = serialize(task)
    return jsonify(body), 201, {"Location": body["url"]}


@bp.put("/tasks/<int:task_id>")
def replace_task(task_id):
    task = storage.get(task_id)
    if task is None:
        return api_error(404, "задача не найдена")
    data, failure = read_json()
    if failure is not None:
        return failure
    problem = service.validate_title(data.get("title"))
    if problem is not None:
        return api_error(422, problem, field="title")
    problem = service.validate_done(data.get("done", False))
    if problem is not None:
        return api_error(422, problem, field="done")

    updated = storage.replace(task_id, data["title"].strip(), bool(data.get("done", False)))
    return jsonify(serialize(updated))


@bp.patch("/tasks/<int:task_id>")
def patch_task(task_id):
    task = storage.get(task_id)
    if task is None:
        return api_error(404, "задача не найдена")
    data, failure = read_json()
    if failure is not None:
        return failure
    if "title" in data:
        problem = service.validate_title(data["title"])
        if problem is not None:
            return api_error(422, problem, field="title")
    if "done" in data:
        problem = service.validate_done(data["done"])
        if problem is not None:
            return api_error(422, problem, field="done")

    updated = storage.patch(task_id, service.apply_patch(task, data))
    return jsonify(serialize(updated))


@bp.delete("/tasks/<int:task_id>")
def delete_task(task_id):
    if not storage.remove(task_id):
        return api_error(404, "задача не найдена")
    return Response(status=204)

